export function getStyleSvg(type: 'shape' | 'corner-square' | 'corner-dot' | 'frame', num: number): SvgData | undefined {
  switch (type) {
    case 'shape': return QRFY_SHAPE_SVGS[num];
    case 'corner-square': return QRFY_BORDER_SVGS[num];
    case 'corner-dot': return QRFY_CENTER_SVGS[num];
    case 'frame': return QRFY_FRAME_SVGS[num];
    default: return undefined;
  }
}
